import itertools,json
jobs='ABCDE'; published='ACEBD'
slot=dict(zip(jobs,[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]))
t=dict(zip(jobs,[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]))
def dist(q):
 perm=[published.index(j) for j in q]; seen=set();cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1
   while i not in seen:seen.add(i);i=perm[i]
 return 5-cycles
classes={i:[] for i in range(3)}
for q in itertools.permutations(jobs):
 d=dist(q)
 if d>2:continue
 pos={j:q.index(j)+1 for j in jobs}
 if pos['A']>=pos['D'] or pos['E'] in (2,3) or pos['D']==5:continue
 nominal=sum(slot[j][i] for i,j in enumerate(q))+sum(t[a][jobs.index(b)] for a,b in zip(q,q[1:]))
 cost=nominal+6*max(0,pos['A']-2)+4*d+(5 if d==2 else 0)
 classes[d].append((cost,''.join(q)))
best=min(v for vs in classes.values() for v in vs)
result={'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(vs)[0] if vs else None for d,vs in classes.items()},'feasible_by_swaps':{str(d):len(vs) for d,vs in classes.items()}}
# Independent breadth-first transposition distance check, including distinct roster counts.
levels=[{published}];seen={published}
for depth in (1,2):
 nxt=set()
 for p in levels[-1]:
  for i,j in itertools.combinations(range(5),2):
   q=list(p);q[i],q[j]=q[j],q[i];nxt.add(''.join(q))
 nxt-=seen;levels.append(nxt);seen|=nxt
for d in range(3):
 valid={q for q in levels[d] if q.index('A')<q.index('D') and q.index('E') not in (1,2) and q.index('D')!=4}
 assert valid=={q for c,q in classes[d]}
print(json.dumps(result))
print('best:',best,'classes:',{d:sorted(vs) for d,vs in classes.items()})

